const CHUNK_CASES_FROM_1022: &str = include_str!("tests_from_1022_chunks.tsv");

#[test]
fn data_fixes_from_1022_match_the_vanilla_oracle() {
    for (ty, from, to, input, expected) in CASES_FROM_1022 {
        assert_eq!(update(ty, *from, *to, input), *expected, "{ty} {from} -> {to}: {input}");
    }
}

#[test]
fn data_fixes_from_1022_that_throw_in_vanilla_panic_with_the_same_message() {
    for (ty, from, to, input, message) in PANIC_CASES_FROM_1022 {
        assert_eq!(update_catching(ty, *from, *to, input), format!("ERR {message}"), "{ty} {from} -> {to}: {input}");
    }
}

#[test]
fn chunks_from_1022_match_the_vanilla_oracle() {
    for line in CHUNK_CASES_FROM_1022.lines() {
        let fields: Vec<&str> = line.splitn(5, '\t').collect();
        let ty: &'static str = Box::leak(fields[0].to_string().into_boxed_str());
        let actual = update(ty, fields[1].parse().unwrap(), fields[2].parse().unwrap(), fields[3]);
        assert!(actual == fields[4], "{ty} {} -> {} produced a different chunk: {}", fields[1], fields[2], &fields[3][..fields[3].len().min(300)]);
    }
}

#[test]
#[ignore]
fn updates_match_the_vanilla_oracle_from_1022() {
    let cases = std::fs::read_to_string(std::env::var("WAFER_DFU_CASES").expect("WAFER_DFU_CASES points at the DfuOracle input")).unwrap();
    let expected = std::fs::read_to_string(std::env::var("WAFER_DFU_EXPECTED").expect("WAFER_DFU_EXPECTED points at the DfuOracle output")).unwrap();
    let mut expected = expected.lines();
    let mut mismatches = 0;
    let mut count = 0;
    for case in cases.lines().filter(|line| !line.is_empty()) {
        let fields: Vec<&str> = case.splitn(4, '\t').collect();
        let ty: &'static str = Box::leak(fields[0].to_string().into_boxed_str());
        let actual = update_catching(ty, fields[1].parse().unwrap(), fields[2].parse().unwrap(), fields[3]);
        let vanilla = expected.next().expect("an expected line");
        count += 1;
        let matches = if let Some(message) = actual.strip_prefix("ERR ") { vanilla.starts_with("ERR ") && vanilla.contains(message) } else { actual == vanilla };
        if !matches {
            mismatches += 1;
            let first_difference = vanilla.bytes().zip(actual.bytes()).position(|(a, b)| a != b).unwrap_or(vanilla.len().min(actual.len()));
            let window = |text: &str| {
                let start = text.floor_char_boundary(first_difference.saturating_sub(300));
                let end = text.floor_char_boundary((first_difference + 300).min(text.len()));
                text[start..end].to_string()
            };
            let head = &case[..case.len().min(200)];
            eprintln!("{head}\n  first difference at {first_difference} of {} / {}\n  vanilla: {}\n  wafer:   {}", vanilla.len(), actual.len(), window(vanilla), window(&actual));
        }
    }
    eprintln!("{count} cases, {mismatches} mismatches");
    assert_eq!(mismatches, 0);
}
